<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { BookOpenCheck, ClipboardCheck, Tags, Users } from '@lucide/vue'
import { api, readableError } from '../../api/client'
import AsyncState from '../../components/AsyncState.vue'
interface Stats{users:number;problems:number;submissions:number}const stats=ref<Stats|null>(null);const state=ref<'loading'|'error'|'ready'>('loading');const error=ref('');async function load(){state.value='loading';try{stats.value=(await api.get<Stats>('/admin/dashboard')).data;state.value='ready'}catch(cause){error.value=readableError(cause,'管理数据加载失败');state.value='error'}}onMounted(load)
</script>
<template><div><div class="page-heading"><div><p class="eyebrow">管理工作台</p><h1 tabindex="-1">校园题库运营概览</h1><p>集中管理题目、用户、标签与评测记录。</p></div></div><AsyncState v-if="state!=='ready'" :status="state" :message="state==='loading'?'正在加载管理概览…':error" :on-retry="load"/><template v-else-if="stats"><section class="stat-grid"><article class="stat-card"><Users/><span>用户总数</span><strong>{{stats.users}}</strong></article><article class="stat-card"><BookOpenCheck/><span>题目总数</span><strong>{{stats.problems}}</strong></article><article class="stat-card"><ClipboardCheck/><span>提交总数</span><strong>{{stats.submissions}}</strong></article></section><section class="admin-actions"><RouterLink class="card action-card" to="/admin/problems"><BookOpenCheck/><h2>题目管理</h2><p>发布、编辑和维护测试点。</p></RouterLink><RouterLink class="card action-card" to="/admin/tags"><Tags/><h2>标签管理</h2><p>创建、重命名和清理题目标签。</p></RouterLink><RouterLink class="card action-card" to="/admin/users"><Users/><h2>用户管理</h2><p>查看账号角色与状态。</p></RouterLink><RouterLink class="card action-card" to="/admin/submissions"><ClipboardCheck/><h2>提交管理</h2><p>查看评测诊断与源码。</p></RouterLink></section></template></div></template>
